    n text,
    name text,
    street text,
    city text,
    county text,
    postal text,
    lat double precision,
    lon double precision,
    url text,
    status text
  )
)
insert into public.texasdefined_brand_locations (
  id, brand_slug, brand_label, banner, location_number, name, street, city, county_slug,
  state, postal_code, latitude, longitude, official_url, source_url, source_checked_at,
  status, public_locator_enabled
)
select
  'academy-' || n,
  'academy',
  'Academy Sports + Outdoors',
  'Academy Sports + Outdoors',
  n,
  name,
  street,
  city,
  county,
  'TX',
  postal,
  lat,
  lon,
  url,
  url,
  date '2026-09-12',
  status,
  status = 'active'
from academy_locations
on conflict (id) do update set
  brand_slug = excluded.brand_slug,
  brand_label = excluded.brand_label,
  banner = excluded.banner,
  location_number = excluded.location_number,
  name = excluded.name,
  street = excluded.street,
  city = excluded.city,
  county_slug = excluded.county_slug,
  state = excluded.state,
  postal_code = excluded.postal_code,
  latitude = excluded.latitude,
  longitude = excluded.longitude,
  official_url = excluded.official_url,
  source_url = excluded.source_url,
  source_checked_at = excluded.source_checked_at,
  status = excluded.status,
  public_locator_enabled = excluded.public_locator_enabled,
  updated_at = now();

do $$
declare
  total_count integer;
  active_public_count integer;
  planned_private_count integer;
begin
  select
    count(*),
    count(*) filter (where status = 'active' and public_locator_enabled = true),
    count(*) filter (where status = 'planned' and public_locator_enabled = false)
  into total_count, active_public_count, planned_private_count
  from public.texasdefined_brand_locations
  where brand_slug = 'academy' and state = 'TX';

  if total_count <> 127 then
    raise exception 'Academy Texas registry expected 127 rows, found %', total_count;
  end if;
  if active_public_count <> 120 then
    raise exception 'Academy Texas public active registry expected 120 rows, found %', active_public_count;
  end if;
  if planned_private_count <> 7 then
    raise exception 'Academy Texas planned private registry expected 7 rows, found %', planned_private_count;
  end if;
end
$$;
